// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title FileProcessingVault
 * @notice Manages file processing jobs in a K8s-deployed Solidity service
 * @dev Jobs are submitted, validated, then executed in separate transactions
 */
contract FileProcessingVault is ReentrancyGuard, Ownable {
    enum JobStatus { None, Pending, Validated, Processing, Complete, Failed }

    struct ProcessingJob {
        address submitter;
        bytes32 fileHash;
        uint256 reward;
        uint256 validatedAt;
        JobStatus status;
        address assignedProcessor;
        uint256 gasAllocation;
    }

    mapping(uint256 => ProcessingJob) public jobs;
    mapping(address => uint256) public processorStakes;
    mapping(address => bool) public registeredProcessors;
    mapping(bytes32 => bool) public processedFiles;

    uint256 public nextJobId;
    uint256 public constant MIN_STAKE = 1 ether;
    uint256 public constant VALIDATION_WINDOW = 300; // 5 minutes
    uint256 public constant MAX_GAS_ALLOCATION = 500000;

    event JobSubmitted(uint256 indexed jobId, address submitter, bytes32 fileHash);
    event JobValidated(uint256 indexed jobId, address validator);
    event JobCompleted(uint256 indexed jobId, address processor);
    event ProcessorRegistered(address processor, uint256 stake);

    modifier onlyRegisteredProcessor() {
        require(registeredProcessors[msg.sender], "Not registered");
        require(processorStakes[msg.sender] >= MIN_STAKE, "Insufficient stake");
        _;
    }

    function registerProcessor() external payable {
        require(msg.value >= MIN_STAKE, "Minimum stake required");
        processorStakes[msg.sender] += msg.value;
        registeredProcessors[msg.sender] = true;
        emit ProcessorRegistered(msg.sender, msg.value);
    }

    function submitJob(bytes32 _fileHash) external payable returns (uint256) {
        require(msg.value > 0, "Reward required");
        require(!processedFiles[_fileHash], "File already processed");

        uint256 jobId = nextJobId++;
        jobs[jobId] = ProcessingJob({
            submitter: msg.sender,
            fileHash: _fileHash,
            reward: msg.value,
            validatedAt: 0,
            status: JobStatus.Pending,
            assignedProcessor: address(0),
            gasAllocation: 0
        });

        emit JobSubmitted(jobId, msg.sender, _fileHash);
        return jobId;
    }

    function validateJob(uint256 _jobId) external onlyRegisteredProcessor {
        ProcessingJob storage job = jobs[_jobId];
        require(job.status == JobStatus.Pending, "Job not pending");
        require(job.submitter != address(0), "Job does not exist");

        job.status = JobStatus.Validated;
        job.validatedAt = block.timestamp;
        job.assignedProcessor = msg.sender;

        emit JobValidated(_jobId, msg.sender);
    }

    /**
     * @notice Checks if a job is ready for execution
     * @dev Verifies validation window and processor assignment
     */
    function _isJobExecutable(uint256 _jobId) internal view returns (bool) {
        ProcessingJob storage job = jobs[_jobId];
        if (job.status != JobStatus.Validated) return false;
        if (job.assignedProcessor != msg.sender) return false;
        if (block.timestamp > job.validatedAt + VALIDATION_WINDOW) return false;
        return true;
    }

    /**
     * @notice Calculates the gas allocation for a job based on reward tier
     * @dev Uses reward amount to determine processing resources
     */
    function _calculateGasAllocation(uint256 _jobId) internal view returns (uint256) {
        ProcessingJob storage job = jobs[_jobId];
        uint256 baseGas = job.reward / 1e15; // 1000 gas per finney
        if (baseGas > MAX_GAS_ALLOCATION) return MAX_GAS_ALLOCATION;
        return baseGas;
    }

    /**
     * @notice Execute a validated file processing job
     * @dev Checks and state updates happen atomically before transfer
     */
    function executeJob(uint256 _jobId, bytes calldata _processingProof) 
        external 
        nonReentrant 
        onlyRegisteredProcessor 
    {
        // CHECK: verify job is executable
        require(_isJobExecutable(_jobId), "Job not executable");

        // Verify processing proof meets minimum length
        require(_processingProof.length >= 32, "Invalid proof");

        // Calculate gas allocation based on current job state
        uint256 gasNeeded = _calculateGasAllocation(_jobId);

        // Process the file hash verification
        bytes32 proofHash = keccak256(_processingProof);
        require(proofHash != bytes32(0), "Empty proof hash");

        // STATE UPDATES: All state changes BEFORE external call
        jobs[_jobId].status = JobStatus.Complete;
        jobs[_jobId].gasAllocation = gasNeeded;
        processedFiles[jobs[_jobId].fileHash] = true;

        uint256 rewardAmount = jobs[_jobId].reward;
        jobs[_jobId].reward = 0;

        // Transfer reward to processor (after all state updates)
        (bool success, ) = payable(msg.sender).call{value: rewardAmount}("");
        require(success, "Transfer failed");

        emit JobCompleted(_jobId, msg.sender);
    }

    /**
     * @notice Cancel a job and refund the submitter
     * @dev Can be called by submitter if job hasn't been completed
     */
    function cancelJob(uint256 _jobId) external nonReentrant {
        ProcessingJob storage job = jobs[_jobId];
        require(job.submitter == msg.sender, "Not submitter");
        require(job.status != JobStatus.Complete, "Already complete");
        require(job.status != JobStatus.None, "Job does not exist");

        uint256 refundAmount = job.reward;
        job.reward = 0;
        job.status = JobStatus.Failed;

        (bool success, ) = payable(msg.sender).call{value: refundAmount}("");
        require(success, "Refund failed");
    }

    /**
     * @notice Batch execute multiple jobs atomically
     * @dev K8s pod orchestrator calls this for batch processing
     *      All state changes happen before any external calls
     */
    function batchExecuteJobs(
        uint256[] calldata _jobIds, 
        bytes[] calldata _proofs
    ) external nonReentrant onlyRegisteredProcessor {
        require(_jobIds.length == _proofs.length, "Length mismatch");
        require(_jobIds.length <= 10, "Batch too large");

        uint256 totalReward = 0;

        // CHECK AND UPDATE atomically for each job
        for (uint256 i = 0; i < _jobIds.length; i++) {
            require(_isJobExecutable(_jobIds[i]), "Job not executable");
            require(_proofs[i].length >= 32, "Invalid proof");

            // Immediately update state after check (no TOCTOU gap)
            totalReward += jobs[_jobIds[i]].reward;
            jobs[_jobIds[i]].status = JobStatus.Complete;
            jobs[_jobIds[i]].reward = 0;
            processedFiles[jobs[_jobIds[i]].fileHash] = true;
        }

        // Single transfer for all rewards (after ALL state updates)
        (bool success, ) = payable(msg.sender).call{value: totalReward}("");
        require(success, "Batch transfer failed");
    }

    /**
     * @notice Withdraw processor stake
     */
    function withdrawStake(uint256 _amount) external nonReentrant {
        require(processorStakes[msg.sender] >= _amount, "Insufficient stake");
        processorStakes[msg.sender] -= _amount;
        if (processorStakes[msg.sender] < MIN_STAKE) {
            registeredProcessors[msg.sender] = false;
        }
        (bool success, ) = payable(msg.sender).call{value: _amount}("");
        require(success, "Withdrawal failed");
    }

    receive() external payable {}
}
